BEGIN;
SELECT plan(17);
INSERT INTO public.booking_staff_unavailability (staff_id,start_at,end_at,reason) VALUES ('00000000-0000-0000-0000-000000000002','2030-01-01T00:00:00Z','2030-01-01T02:00:00Z','DEV-203 test blockout');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT lives_ok($$ SELECT public.create_admin_meeting('ADMIN_MEETING','2026-10-29T23:00:00Z','2026-10-30T00:00:00Z',ARRAY['10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002']::uuid[]) $$,'admin meetings accept multiple students and no staff');
SELECT lives_ok($$ SELECT public.create_admin_meeting('ADMIN_MEETING','2020-01-01T00:00:00Z','2020-01-01T01:00:00Z') $$,'admin can book arbitrary past times without a student or subject');
SELECT throws_ok($$ SELECT public.create_admin_meeting('CLASS','2026-10-29T00:00:00Z','2026-10-29T01:00:00Z') $$,'P0001','Unsupported manual meeting type','recurring offerings retain their own workflow');
SELECT throws_ok($$ SELECT public.create_admin_meeting('CHECK_IN','2026-10-29T01:00:00Z','2026-10-29T00:00:00Z') $$,'P0001','Choose a valid start time and positive duration','invalid time ranges are rejected');
SELECT lives_ok($$ SELECT public.admin_meeting_warnings('CHECK_IN','2026-10-29T00:00:00Z','2026-10-29T01:00:00Z',ARRAY['00000000-0000-0000-0000-000000000001']::uuid[]) $$,'advisory evaluator supports check-ins at arbitrary times');
SELECT ok(EXISTS (SELECT 1 FROM public.admin_meeting_warnings('ADMIN_MEETING','2030-01-01T00:30:00Z','2030-01-01T01:30:00Z',ARRAY['00000000-0000-0000-0000-000000000002']::uuid[]) WHERE reason='Staff has a blockout'),'exact-window evaluator warns about an overlapping staff blockout');
SELECT lives_ok($$ SELECT public.create_admin_meeting('ADMIN_MEETING','2030-01-01T00:30:00Z','2030-01-01T01:30:00Z','{}','{}',ARRAY['00000000-0000-0000-0000-000000000002']::uuid[]) $$,'admin may confirm despite that blockout');
CREATE TEMP TABLE meeting_review_test AS SELECT public.create_admin_meeting('TRIAL_SESSION','2030-01-01T00:30:00Z','2030-01-01T01:30:00Z',ARRAY['10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002']::uuid[],ARRAY['60000000-0000-0000-0000-000000000001']::uuid[],ARRAY['00000000-0000-0000-0000-000000000002']::uuid[]) id;
ALTER TABLE meeting_review_test ADD COLUMN token text;
RESET ROLE;
UPDATE public.sessions SET booking_public_token='abcdefghijklmnopqrstuv' WHERE id=(SELECT id FROM meeting_review_test);
UPDATE meeting_review_test SET token='abcdefghijklmnopqrstuv';
SET LOCAL ROLE authenticated;
SELECT is((SELECT type FROM public.sessions_staff WHERE session_id=(SELECT id FROM meeting_review_test)),'TRIAL_TUTOR','trial booking preserves Trial Tutor assignment metadata');
SELECT is(public.create_admin_meeting('TRIAL_SESSION','2030-01-02T00:30:00Z','2030-01-02T01:30:00Z',ARRAY['10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002']::uuid[],'{}',ARRAY['00000000-0000-0000-0000-000000000010']::uuid[],NULL,(SELECT id FROM meeting_review_test)),(SELECT id FROM meeting_review_test),'rescheduling preserves Session identity');
SELECT ok((SELECT planned_absence FROM public.sessions_staff WHERE session_id=(SELECT id FROM meeting_review_test) AND staff_id='00000000-0000-0000-0000-000000000002'),'removed staff history remains as a planned absence');
SELECT is((SELECT type FROM public.sessions_staff WHERE session_id=(SELECT id FROM meeting_review_test) AND staff_id='00000000-0000-0000-0000-000000000010'),'TRIAL_TUTOR','replacement staff retain trial assignment type');
SELECT throws_ok($$ SELECT public.create_admin_meeting('TRIAL_SESSION','2030-01-02T00:30:00Z','2030-01-02T01:30:00Z','{}','{}','{}',NULL,(SELECT id FROM meeting_review_test)) $$,'P0001','Remove existing students through Log absence before rescheduling','removing existing students requires the explicit absence/billing workflow');
SELECT is((SELECT count(*)::integer FROM public.sessions_parents WHERE session_id=(SELECT id FROM meeting_review_test)),0,'parent selections are reconciled on reschedule');
SELECT is((SELECT booking_public_token FROM public.sessions WHERE id=(SELECT id FROM meeting_review_test)),(SELECT token FROM meeting_review_test),'rescheduling preserves the durable management link');
CREATE TEMP TABLE meeting_role_test AS SELECT public.create_admin_meeting('CHECK_IN','2030-01-01T00:30:00Z','2030-01-01T01:30:00Z','{}','{}',ARRAY['00000000-0000-0000-0000-000000000002']::uuid[]) id;
SELECT public.create_admin_meeting('CHECK_IN','2030-01-01T00:30:00Z','2030-01-01T01:30:00Z','{}','{}',ARRAY['00000000-0000-0000-0000-000000000002']::uuid[],NULL,(SELECT id FROM meeting_role_test),ARRAY['00000000-0000-0000-0000-000000000002']::uuid[]);
SELECT is((SELECT type FROM public.sessions_staff WHERE session_id=(SELECT id FROM meeting_role_test)),'CHECK_IN_RECEIVER','rescheduling persists changes to an existing staff role');
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT throws_ok($$ SELECT public.create_admin_meeting('CHECK_IN','2026-10-29T00:00:00Z','2026-10-29T01:00:00Z') $$,'42501','Active AdminStaff access required','students cannot create unrestricted admin meetings');
SELECT throws_ok($$ SELECT public.admin_meeting_warnings('CHECK_IN','2026-10-29T00:00:00Z','2026-10-29T01:00:00Z','{}') $$,'42501','Active AdminStaff access required','students cannot inspect staff availability through this boundary');
SELECT * FROM finish();
ROLLBACK;
